    localparam int LEN_W = $clog2(RATE_BYTES + 1);   // 8, = sha3_256 valid_bytes width

    // Latched request. config_sh_q / imem_sh_q shift right by one byte per consumed byte.
    logic [TILE_ID_BITS-1:0]    tile_id_q;
    logic [CONFIG_MAX_BITS-1:0] config_sh_q;
    logic [IMEM_MAX_BITS-1:0]   imem_sh_q;
    logic [CONFIG_LEN_BITS-1:0] config_len_q;

