        req_len_ok = (req_len <= MEASURE_MSG_MAX_BYTES);
    end

    // Source of the next byte: tile id (7-way select), else config low byte, else imem low byte.
    always_comb begin
        from_tile   = (build_idx_q < LEN_W'(TILE_ID_BYTES));
        from_config = !from_tile && (build_idx_q < LEN_W'(TILE_ID_BYTES) + LEN_W'(config_len_q));
        build_byte  = imem_sh_q[7:0];
        if (from_config) build_byte = config_sh_q[7:0];
        if (from_tile) begin
            build_byte = 8'h00;
            for (int i = 0; i < TILE_ID_BYTES; i++)
