        .rst_n        (rst_n),
        .start        (sha3_start_q),
        .msg_block_in (msg_block_q),
        .valid_bytes  (sha3_valid_bytes_q),
        .is_final     (sha3_is_final_q),
        .digest       (sha3_digest),
        .busy         (sha3_busy),
        .done         (sha3_done),
        .p_start     (p_start),
        .p_state_in  (p_state_in),
        .p_state_out (p_state_out),
        .p_busy      (p_busy),
        .p_done      (p_done)
