    typedef enum logic [2:0] {
        S_IDLE  = 3'd0,
        S_BUILD = 3'd4,     // D-SYN-2: one message byte per cycle
        S_SHA3  = 3'd1,     // one-cycle start pulse to sha3_256
        S_WAIT  = 3'd2,
        S_DONE  = 3'd3
