    assign busy = (state_q == S_BUILD) || (state_q == S_SHA3) || (state_q == S_WAIT);

    always_ff @(posedge clk) begin
        if (!rst_n) begin
            state_q            <= S_IDLE;
            tile_id_q          <= '0;
            config_sh_q        <= '0;
            imem_sh_q          <= '0;
            config_len_q       <= '0;
            msg_block_q        <= '0;
            build_idx_q        <= '0;
            sha3_start_q       <= 1'b0;
            sha3_valid_bytes_q <= '0;
            sha3_is_final_q    <= 1'b0;
            measurement        <= '0;
            done               <= 1'b0;
