                S_IDLE: begin
                    if (start && req_len_ok) begin
                        tile_id_q          <= tile_id;
                        config_sh_q        <= config_data;
                        imem_sh_q          <= imem;
                        config_len_q       <= config_len;
                        msg_block_q        <= {1'b1, {(RATE_BITS-1){1'b0}}};   // S3-A6: SHA3 end bit preset; bytes >= req_len stay zero
