                S_SHA3: begin
                    sha3_start_q <= 1'b1;
                    state_q      <= S_WAIT;
                end

                S_WAIT: begin
                    if (sha3_done) begin
                        measurement <= sha3_digest;
                        state_q     <= S_DONE;
                    end
                end

                S_DONE: begin
                    done    <= 1'b1;
                    state_q <= S_IDLE;
